17	export async function POST(request: Request) {
18	  const formData = await request.formData();
19	  
20	  const grantType = formData.get('grant_type') as string;
21	  const code = formData.get('code') as string;
22	  const redirectUri = formData.get('redirect_uri') as string;
23	  const clientId = formData.get('client_id') as string;
24	  const clientSecret = formData.get('client_secret') as string;
25	  const codeVerifier = formData.get('code_verifier') as string;
26	
27	  // grant_type のバリデーション
28	  if (grantType !== 'authorization_code') {
29	    return NextResponse.json(
30	      createOAuthError('unsupported_grant_type'),
31	      { status: 400 }
32	    );
33	  }
34	
35	  // 必須パラメータのチェック
36	  if (!code || !redirectUri || !clientId || !clientSecret || !codeVerifier) {
37	    return NextResponse.json(
38	      createOAuthError('invalid_request', 'Missing required parameters'),
39	      { status: 400 }
40	    );
41	  }
42	
43	  // トークンエンドポイントはサーバー間通信（Cookie なし）なので
44	  // RLS をバイパスする Admin クライアントを使用
45	  const supabase = await createAdminClient();
46	
47	  // クライアント認証（RPC経由）
48	  const { data: applications, error: appError } = await supabase
49	    .rpc('get_application_by_client_id', { p_client_id: clientId });
50	
51	  const application = applications?.[0];
52	
53	  if (appError || !application) {
54	    return NextResponse.json(
55	      createOAuthError('invalid_client'),
56	      { status: 401 }
57	    );
58	  }
59	
60	  // クライアントシークレットの検証
61	  const isValidSecret = await verifyClientSecret(clientSecret, application.client_secret_hash);
62	  if (!isValidSecret) {
63	    return NextResponse.json(
64	      createOAuthError('invalid_client', 'Invalid client credentials'),
65	      { status: 401 }
66	    );
67	  }
68	
69	  // 認可コードを取得（RPC経由）
70	  const { data: authCodes, error: codeError } = await supabase
71	    .rpc('get_authorization_code', { p_code: code });
72	
73	  const authCode = authCodes?.[0];
74	
75	  if (codeError || !authCode) {
76	    return NextResponse.json(
77	      createOAuthError('invalid_grant', 'Invalid or expired authorization code'),
78	      { status: 400 }
79	    );
80	  }
81	
82	  // 認可コードの検証
83	  if (authCode.application_id !== application.id) {
84	    return NextResponse.json(
85	      createOAuthError('invalid_grant', 'Code was issued to different client'),
86	      { status: 400 }
87	    );
88	  }
89	
