91	    return NextResponse.json(
92	      createOAuthError('invalid_grant', 'Redirect URI mismatch'),
93	      { status: 400 }
94	    );
95	  }
96	
97	  // 有効期限チェック
98	  if (new Date(authCode.expires_at) < new Date()) {
99	    // 期限切れコードを削除（RPC経由）
